```c
#include <stdio.h>
#include <stdlib.h>

#define INF 2000000000000000LL

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *a = (long long *)malloc(n * sizeof(long long));
    long long *l = (long long *)malloc(n * sizeof(long long));
    long long *r = (long long *)malloc(n * sizeof(long long));

    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
    }

    // Passada da esquerda para a direita
    long long cur = INF;
    for (int i = 0; i < n; i++) {
        if (cur < INF) {
            cur++;
        }
        if (a[i] != -1) {
            if (a[i] < cur) {
                cur = a[i];
            }
        }
        l[i] = cur;
    }

    // Passada da direita para a esquerda
    cur = INF;
    for (int i = n - 1; i >= 0; i--) {
        if (cur < INF) {
            cur++;
        }
        if (a[i] != -1) {
            if (a[i] < cur) {
                cur = a[i];
            }
        }
        r[i] = cur;
    }

    // O resultado para cada degrau é o mínimo entre os limites
    for (int i = 0; i < n; i++) {
        long long ans = l[i] < r[i] ? l[i] : r[i];
        if (i > 0) printf(" ");
        printf("%lld", ans);
    }
    printf("\n");

    free(a);
    free(l);
    free(r);

    return 0;
}
```

